"use client";

import { createContext, useContext, useState, useCallback, type ReactNode } from "react";
import ConfirmDialog, { type RequireConfirmationInput } from "./confirm-dialog";

export type { RequireConfirmationInput };

export interface ConfirmOptions {
  title?: string;
  description?: string;
  confirmButtonText?: string;
  cancelButtonText?: string;
  variant?: "default" | "destructive";
  requireConfirmationInput?: RequireConfirmationInput;
}

export interface ConfirmDialogMessages {
  title: string;
  description: string;
  confirmButtonText: string;
  cancelButtonText: string;
  requireConfirmationLabel: string;
}

export interface ConfirmDialogProviderProps {
  children: ReactNode;
  messages?: Partial<ConfirmDialogMessages>;
  defaultVariant?: ConfirmOptions["variant"];
}

interface ConfirmContextType {
  confirm: (options: ConfirmOptions) => Promise<boolean>;
}

const ConfirmContext = createContext<ConfirmContextType | undefined>(undefined);

const DEFAULT_CONFIRM_MESSAGES: ConfirmDialogMessages = {
  title: "Confirm Action",
  description: "Are you sure you want to proceed?",
  confirmButtonText: "Confirm",
  cancelButtonText: "Cancel",
  requireConfirmationLabel: "Type {{confirmTerm}} to confirm",
};

export const ConfirmDialogProvider = ({
  children,
  messages,
  defaultVariant = "default",
}: ConfirmDialogProviderProps) => {
  const [options, setOptions] = useState<ConfirmOptions>({});
  const [isOpen, setIsOpen] = useState(false);
  const [resolver, setResolver] = useState<((value: boolean) => void) | null>(null);
  const resolvedMessages = {
    ...DEFAULT_CONFIRM_MESSAGES,
    ...messages,
  };

  const confirm = useCallback((confirmOptions: ConfirmOptions) => {
    setResolver((prev: ((value: boolean) => void) | null) => {
      if (prev) {
        prev(false);
      }
      return null;
    });

    setOptions(confirmOptions);
    setIsOpen(true);
    return new Promise<boolean>((resolve) => {
      setResolver(() => resolve);
    });
  }, []);

  const handleConfirm = () => {
    if (resolver) {
      resolver(true);
    }
    setIsOpen(false);
    setResolver(null);
  };

  const handleCancel = () => {
    if (resolver) {
      resolver(false);
    }
    setIsOpen(false);
    setResolver(null);
  };

  return (
    <ConfirmContext.Provider value={{ confirm }}>
      {children}
      <ConfirmDialog
        isOpen={isOpen}
        title={options.title ?? resolvedMessages.title}
        description={options.description ?? resolvedMessages.description}
        confirmButtonText={options.confirmButtonText ?? resolvedMessages.confirmButtonText}
        cancelButtonText={options.cancelButtonText ?? resolvedMessages.cancelButtonText}
        variant={options.variant ?? defaultVariant}
        requireConfirmationInput={options.requireConfirmationInput}
        requireConfirmationLabel={resolvedMessages.requireConfirmationLabel}
        onConfirm={handleConfirm}
        onCancel={handleCancel}
      />
    </ConfirmContext.Provider>
  );
};

export const useConfirm = () => {
  const context = useContext(ConfirmContext);
  if (!context) {
    throw new Error("useConfirm must be used within a ConfirmDialogProvider");
  }
  return context.confirm;
};

"use client";

import { useState } from "react";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/c-ui/provider-alert-dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";

export interface RequireConfirmationInput {
  confirmTerm: string;
  /** Custom label with {{confirmTerm}} placeholder for the required term (bold). Default: "Type {{confirmTerm}} to confirm" */
  label?: string;
  hint?: string;
}

interface ConfirmDialogProps {
  title: string;
  description: string;
  confirmButtonText: string;
  cancelButtonText: string;
  onConfirm: () => void;
  onCancel: () => void;
  variant: "default" | "destructive";
  isOpen: boolean;
  requireConfirmationInput?: RequireConfirmationInput;
  requireConfirmationLabel: string;
}

const ConfirmDialog = (props: ConfirmDialogProps) => {
  const [typedValue, setTypedValue] = useState("");

  const requireTyped = props.requireConfirmationInput;
  const requiredTerm = requireTyped?.confirmTerm ?? "";
  const canConfirm = !requireTyped || typedValue === requiredTerm;

  const labelMessage = requireTyped?.label ?? props.requireConfirmationLabel;
  const labelParts = labelMessage.split("{{confirmTerm}}");

  return (
    <AlertDialog
      open={props.isOpen}
      onOpenChange={(open) => {
        if (!open) {
          setTypedValue("");
          props.onCancel();
        }
      }}
    >
      <AlertDialogContent>
        <AlertDialogHeader>
          <AlertDialogTitle>{props.title}</AlertDialogTitle>
          <AlertDialogDescription>{props.description}</AlertDialogDescription>
        </AlertDialogHeader>
        {requireTyped && (
          <div className="grid gap-2">
            <Label htmlFor="confirm-type-input">
              <span>
                {labelParts.map((part, i) =>
                  i < labelParts.length - 1 ? (
                    <span key={i}>
                      {part}
                      <span className="font-bold">{requiredTerm}</span>
                    </span>
                  ) : (
                    <span key={i}>{part}</span>
                  ),
                )}
              </span>
            </Label>
            <Input
              id="confirm-type-input"
              value={typedValue}
              onChange={(e) => setTypedValue(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === "Enter" && canConfirm) {
                  e.preventDefault();
                  setTypedValue("");
                  props.onConfirm();
                }
              }}
              placeholder={requiredTerm}
              autoComplete="off"
            />
            {requireTyped.hint && (
              <p className="text-xs text-muted-foreground">{requireTyped.hint}</p>
            )}
          </div>
        )}
        <AlertDialogFooter>
          <AlertDialogCancel
            className="transition-transform duration-150 active:scale-[0.97]"
            onClick={(e) => {
              e.preventDefault();
              setTypedValue("");
              props.onCancel();
            }}
          >
            {props.cancelButtonText}
          </AlertDialogCancel>
          <AlertDialogAction
            variant={props.variant}
            className="transition-transform duration-150 active:scale-[0.97]"
            disabled={!canConfirm}
            onClick={(e) => {
              e.preventDefault();
              setTypedValue("");
              props.onConfirm();
            }}
          >
            {props.confirmButtonText}
          </AlertDialogAction>
        </AlertDialogFooter>
      </AlertDialogContent>
    </AlertDialog>
  );
};

export default ConfirmDialog;

"use client";

import * as React from "react";
import { AlertDialog as AlertDialogPrimitive } from "@base-ui/react/alert-dialog";
import { cn } from "@/lib/utils";

import { Button } from "@/components/ui/button";

function AlertDialog({ ...props }: AlertDialogPrimitive.Root.Props) {
  return <AlertDialogPrimitive.Root data-slot="alert-dialog" {...props} />;
}

function AlertDialogTrigger({ ...props }: AlertDialogPrimitive.Trigger.Props) {
  return <AlertDialogPrimitive.Trigger data-slot="alert-dialog-trigger" {...props} />;
}

function AlertDialogPortal({ ...props }: AlertDialogPrimitive.Portal.Props) {
  return <AlertDialogPrimitive.Portal data-slot="alert-dialog-portal" {...props} />;
}

function AlertDialogOverlay({
  className,
  ...props
}: Omit<AlertDialogPrimitive.Backdrop.Props, "className"> & { className?: string }) {
  return (
    <AlertDialogPrimitive.Backdrop
      data-slot="alert-dialog-overlay"
      className={cn(
        "fixed inset-0 isolate z-50 bg-black/10 duration-100 supports-backdrop-filter:backdrop-blur-xs motion-reduce:animate-none motion-reduce:transition-none data-open:animate-in data-open:fade-in-0 data-closed:animate-out data-closed:fade-out-0",
        className,
      )}
      {...props}
    />
  );
}

function AlertDialogContent({
  className,
  size = "default",
  ...props
}: Omit<AlertDialogPrimitive.Popup.Props, "className"> & { className?: string } & {
  size?: "default" | "sm";
}) {
  return (
    <AlertDialogPortal>
      <AlertDialogOverlay />
      <AlertDialogPrimitive.Popup
        data-slot="alert-dialog-content"
        data-size={size}
        className={cn(
          "group/alert-dialog-content fixed top-1/2 left-1/2 z-50 grid w-full -translate-x-1/2 -translate-y-1/2 gap-4 rounded-xl bg-background p-4 ring-1 ring-foreground/10 duration-100 outline-none data-[size=default]:max-w-xs data-[size=sm]:max-w-xs motion-reduce:animate-none motion-reduce:transition-none data-[size=default]:sm:max-w-sm data-open:animate-in data-open:fade-in-0 data-open:zoom-in-95 data-closed:animate-out data-closed:fade-out-0 data-closed:zoom-out-95",
          className,
        )}
        {...props}
      />
    </AlertDialogPortal>
  );
}

function AlertDialogHeader({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="alert-dialog-header"
      className={cn(
        "grid grid-rows-[auto_1fr] place-items-center gap-1.5 text-center has-data-[slot=alert-dialog-media]:grid-rows-[auto_auto_1fr] has-data-[slot=alert-dialog-media]:gap-x-4 sm:group-data-[size=default]/alert-dialog-content:place-items-start sm:group-data-[size=default]/alert-dialog-content:text-left sm:group-data-[size=default]/alert-dialog-content:has-data-[slot=alert-dialog-media]:grid-rows-[auto_1fr]",
        className,
      )}
      {...props}
    />
  );
}

function AlertDialogFooter({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="alert-dialog-footer"
      className={cn(
        "-mx-4 -mb-4 flex flex-col-reverse gap-2 rounded-b-xl border-t bg-muted/50 p-4 group-data-[size=sm]/alert-dialog-content:grid group-data-[size=sm]/alert-dialog-content:grid-cols-2 sm:flex-row sm:justify-end",
        className,
      )}
      {...props}
    />
  );
}

function AlertDialogMedia({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="alert-dialog-media"
      className={cn(
        "mb-2 inline-flex size-10 items-center justify-center rounded-md bg-muted sm:group-data-[size=default]/alert-dialog-content:row-span-2 *:[svg:not([class*='size-'])]:size-6",
        className,
      )}
      {...props}
    />
  );
}

function AlertDialogTitle({
  className,
  ...props
}: Omit<React.ComponentProps<typeof AlertDialogPrimitive.Title>, "className"> & {
  className?: string;
}) {
  return (
    <AlertDialogPrimitive.Title
      data-slot="alert-dialog-title"
      className={cn(
        "text-base font-medium sm:group-data-[size=default]/alert-dialog-content:group-has-data-[slot=alert-dialog-media]/alert-dialog-content:col-start-2",
        className,
      )}
      {...props}
    />
  );
}

function AlertDialogDescription({
  className,
  ...props
}: Omit<React.ComponentProps<typeof AlertDialogPrimitive.Description>, "className"> & {
  className?: string;
}) {
  return (
    <AlertDialogPrimitive.Description
      data-slot="alert-dialog-description"
      className={cn(
        "text-sm text-balance text-muted-foreground md:text-pretty *:[a]:underline *:[a]:underline-offset-3 *:[a]:hover:text-foreground",
        className,
      )}
      {...props}
    />
  );
}

function AlertDialogAction({
  className,
  ...props
}: Omit<React.ComponentProps<typeof Button>, "className"> & { className?: string }) {
  return <Button data-slot="alert-dialog-action" className={cn(className)} {...props} />;
}

function AlertDialogCancel({
  className,
  variant = "outline",
  size = "default",
  ...props
}: Omit<AlertDialogPrimitive.Close.Props, "className"> & { className?: string } & Pick<
    Omit<React.ComponentProps<typeof Button>, "className"> & { className?: string },
    "variant" | "size"
  >) {
  return (
    <AlertDialogPrimitive.Close
      data-slot="alert-dialog-cancel"
      className={cn(className)}
      render={<Button variant={variant} size={size} />}
      {...props}
    />
  );
}

export {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogMedia,
  AlertDialogOverlay,
  AlertDialogPortal,
  AlertDialogTitle,
  AlertDialogTrigger,
};
